22.     .Append(mlContext.Transforms.Concatenate("Features",
23.         nameof(ChurnRaw.Age), nameof(ChurnRaw.Income), "RegionEncoded", nameof(ChurnRaw.PurchaseHistory)))
24.     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
25.     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
