     .Fit(rawData).Transform(rawData);

 var rowCount = (int)mappedData.GetColumn<bool>("Label").Count();
 var canSplit = rowCount >= 10;

 var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(ChurnRaw.Region))
