         nameof(ChurnRaw.Age), nameof(ChurnRaw.Income), "RegionEncoded", nameof(ChurnRaw.PurchaseHistory)))
     .Append(mlContext.Transforms.NormalizeMinMax("Features"))
     .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
         labelColumnName: "Label", featureColumnName: "Features"));

 IDataView trainData, evalData;
 if (canSplit)
 {
     var split = mlContext.Data.TrainTestSplit(mappedData, testFraction: 0.2);
     trainData = split.TrainSet;
     evalData = split.TestSet;
 }
 else
 {
     // Dataset too small to split — train and evaluate on full data
     Console.WriteLine($"Warning: Only {rowCount} rows — training and evaluating on full dataset.");
     trainData = mappedData;
     evalData = mappedData;
 }

